counterexample:
INSERT INTO t1 (c1, c2) VALUES ('X', 'x2');
INSERT INTO t2 (c1, c2) VALUES ('K', 'k2');
INSERT INTO t3 (c1, c2) VALUES ('A', 'a2');
INSERT INTO t3 (c1, c2) VALUES ('B', 'b2');

-- t4 rows share c2='X' but have different c3 sums per c1
INSERT INTO t4 (c1, c2, c3) VALUES ('A', 'X', 1);
INSERT INTO t4 (c1, c2, c3) VALUES ('B', 'X', 5);

-- t6 provides the same t2 key 'K' for both A and B
INSERT INTO t6 (c1, c2) VALUES ('A', 'K');
INSERT INTO t6 (c1, c2) VALUES ('B', 'K');

-- t5 links t1 'X' to t2 'K'
INSERT INTO t5 (c1, c2, c3) VALUES ('X', 'K', 1.00);

